<script setup lang="ts">
import { router, useForm } from '@inertiajs/vue3'; import { Pencil, Search, UsersRound } from 'lucide-vue-next'; import { computed, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import Button from '@/Core/Components/Button.vue'; import Card from '@/Core/Components/Card.vue'; import DataTable, { type Column } from '@/Core/Components/DataTable.vue'; import EmptyState from '@/Core/Components/EmptyState.vue'; import Input from '@/Core/Components/Input.vue'; import Modal from '@/Core/Components/Modal.vue'; import PageHeader from '@/Core/Components/PageHeader.vue'; import Pagination from '@/Core/Components/Pagination.vue'; import Select from '@/Core/Components/Select.vue'; import { useFormat } from '@/Core/composables/useFormat'; import TenantLayout from '@/Core/Layouts/TenantLayout.vue'; import { route } from '@/Core/lib/route'; import type { Paginated } from '@/Core/types'; import CrmStatusBadge from '../../../Components/CrmStatusBadge.vue'; import SalesNav from '../../../Components/SalesNav.vue'; import type { CustomerLifecycleStage, CustomerProfile } from '../../../Components/types';
defineOptions({ layout: TenantLayout }); const props = defineProps<{ customers: Paginated<CustomerProfile>; filters: { search: string; stage: CustomerLifecycleStage | null; segment: string | null }; stages: CustomerLifecycleStage[]; segments: Array<{ id: string; name: string }> }>(); const { t } = useI18n(); const format = useFormat(); const search = ref(props.filters.search); const stage = ref(props.filters.stage ?? ''); const segment = ref(props.filters.segment ?? ''); const target = ref<CustomerProfile | null>(null); const open = ref(false); const form = useForm({ stage: 'lead' as CustomerLifecycleStage, next_follow_up_at: '' }); const stageOptions = computed(() => [{ value: '', label: t('crm.common.all') }, ...props.stages.map((value) => ({ value, label: t(`crm.status.${value}`) }))]); const segmentOptions = computed(() => [{ value: '', label: t('crm.common.all') }, ...props.segments.map((item) => ({ value: item.id, label: item.name }))]); const columns = computed<Column[]>(() => [{ key: 'name', label: t('crm.sales.customers.title') }, { key: 'stage', label: t('crm.fields.stage') }, { key: 'value', label: t('crm.sales.customers.lifetimeValue') }, { key: 'followUp', label: t('crm.sales.customers.nextFollowUp') }, { key: 'owner', label: t('crm.fields.owner'), hideable: true }, { key: 'actions', label: t('crm.common.actions'), srOnly: true, align: 'right' }]); function apply(): void { router.get(route('crm.sales.customers.index'), { search: search.value || undefined, stage: stage.value || undefined, segment: segment.value || undefined }, { preserveState: true, replace: true }); } function edit(item: CustomerProfile): void { target.value = item; form.stage = item.stage; form.next_follow_up_at = item.nextFollowUpAt?.slice(0, 16) ?? ''; form.clearErrors(); open.value = true; } function submit(): void { if (!target.value) return; form.patch(route('crm.sales.customers.update', { customerProfile: target.value.id }), { preserveScroll: true, onSuccess: () => { open.value = false; } }); }
</script>
<template><PageHeader :eyebrow="t('crm.eyebrow')" :title="t('crm.sales.customers.title')" :description="t('crm.sales.customers.description')" /><SalesNav current="customers" /><Card flush><DataTable :columns="columns" :rows="customers.data" row-key="id" :caption="t('crm.sales.customers.title')" storage-key="crm-customers"><template #toolbar><form class="flex min-w-0 flex-1 flex-wrap items-end gap-2" @submit.prevent="apply"><Input v-model="search" :label="t('crm.sales.customers.search')" class="min-w-48 flex-1" type="search"><template #leading><Search class="size-4" aria-hidden="true" /></template></Input><Select v-model="stage" :options="stageOptions" :label="t('crm.fields.stage')" class="w-full sm:w-44" /><Select v-model="segment" :options="segmentOptions" :label="t('crm.settings.segments')" class="w-full sm:w-48" /><Button type="submit" size="sm">{{ t('crm.common.search') }}</Button></form></template><template #cell-name="{ row }"><div><Button variant="ghost" size="sm" :href="route('crm.sales.customers.show', { customerProfile: row.id })" class="max-w-full truncate">{{ row.company?.name ?? row.contact?.name }}</Button><p class="px-3 text-xs text-ink-subtle">{{ row.company?.email ?? row.contact?.email }}</p></div></template><template #cell-stage="{ row }"><CrmStatusBadge :status="row.stage" /></template><template #cell-value="{ row }"><div class="grid gap-0.5"><span v-for="(amount, currency) in row.lifetimeValues" :key="currency" class="tabular font-mono text-sm">{{ format.money(amount, currency) }}</span><span v-if="Object.keys(row.lifetimeValues).length === 0">{{ t('crm.common.notSet') }}</span></div></template><template #cell-followUp="{ row }"><span class="tabular text-ink-muted">{{ row.nextFollowUpAt ? format.date(row.nextFollowUpAt, 'datetime') : t('crm.common.notSet') }}</span></template><template #cell-owner="{ row }"><span class="text-ink-muted">{{ row.owner?.name ?? t('crm.common.unassigned') }}</span></template><template #cell-actions="{ row }"><Button v-if="row.editable" icon size="sm" variant="ghost" :aria-label="t('crm.sales.customers.edit')" @click="edit(row)"><template #icon><Pencil class="size-4" aria-hidden="true" /></template></Button></template><template #empty><EmptyState :title="t('crm.sales.customers.empty')"><template #icon><UsersRound /></template></EmptyState></template></DataTable><Pagination :meta="customers" /></Card><Modal v-model:open="open" :title="t('crm.sales.customers.edit')" :persistent="form.processing"><form id="crm-customer-form" class="grid gap-4" @submit.prevent="submit"><Select v-model="form.stage" :options="stages.map((value) => ({ value, label: t(`crm.status.${value}`) }))" :label="t('crm.fields.stage')" :error="form.errors.stage" /><Input v-model="form.next_follow_up_at" type="datetime-local" :label="t('crm.sales.customers.nextFollowUp')" :error="form.errors.next_follow_up_at" optional /></form><template #footer><Button variant="ghost" @click="open = false">{{ t('crm.common.cancel') }}</Button><Button form="crm-customer-form" type="submit" variant="primary" :loading="form.processing">{{ t('crm.common.save') }}</Button></template></Modal></template>
